using namespace std;

// Function to check if a string is palindrome
bool isPalindrome(string &s) {
    int n = s.length();

    // compare each character from starting
    // with its corresponding character from last
    for (int i = 0; i < n/2; i++ )
        if (s[i] != s[n-i-1])
            return false;

    return true;
}

// Function to check if a palindrome pair exists
bool palindromePair(vector<string> &arr) {

    // Consider each pair one by one
    for (int i = 0; i < arr.size(); i++) {
        for (int j = i + 1; j< arr.size(); j++) {

            // concatenate both strings
            string str = arr[i] + arr[j];

            // check if str is palindrome
            if (isPalindrome(str))
                return true;

            // check for other combination
            str = arr[j] + arr[i];
            if (isPalindrome(str))
                return true;
        }
    }
    return false;
}

int main() {
    vector <string> arr = {"geekf", "geeks", "or", "keeg", "abc", "bc"};
    if(palindromePair(arr))
        cout << "True";
    else
        cout << "False";
    return 0;
}


